func main() {
	flag.Parse()

	if *help {
		printHelp()
		os.Exit(0)
	}

	if *version {
		fmt.Printf("yq (https://github.com/mikefarah/yq/) version %s\n", Version)
		os.Exit(0)
	}

	args := flag.Args()

	// Determine the command
	cmd := "eval"
	exprArg := ""
	fileArgs := []string{}

	if len(args) > 0 {
		firstArg := args[0]
		if firstArg == "eval" || firstArg == "eval-all" || firstArg == "completion" || firstArg == "help" {
			cmd = firstArg
			exprArg = ""
			fileArgs = args[1:]
		} else {
			exprArg = firstArg
			fileArgs = args[1:]
		}
	}

	// Get expression
	expr := *expression
	if expr == "" {
		if *fromFile != "" {
			content, err := os.ReadFile(*fromFile)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				os.Exit(1)
			}
			expr = string(content)
		} else if exprArg != "" {
			expr = exprArg
		}
	}

	if expr == "" && !*nullInput {
		if len(fileArgs) > 0 {
			expr = fileArgs[0]
			fileArgs = fileArgs[1:]
		}
	}

	// If no files, read from stdin
	if len(fileArgs) == 0 && !*nullInput {
		fileArgs = []string{}
	}

	// Handle different commands
	switch cmd {
	case "eval-all":
		handleEvalAll(expr, fileArgs)
	case "eval":
		handleEval(expr, fileArgs)
	case "completion":
		handleCompletion(fileArgs)
	case "help":
		printHelp()
	}
}

func handleEval(expr string, files []string) {
	hasMatch := false

	if *nullInput {
		// Parse the expression and evaluate with null input
		query, err := gojq.Parse(expr)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}

		iter := query.Run(nil)
		for {
			v, ok := iter.Next()
			if !ok {
				break
			}
			if err, ok := v.(error); ok {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				continue
			}
			hasMatch = true
			outputValue(v)
		}
	} else if len(files) == 0 {
		// Read from stdin
		scanner := bufio.NewScanner(os.Stdin)
		var input []byte
		for scanner.Scan() {
			input = append(input, scanner.Bytes()...)
			input = append(input, '\n')
		}

		data := parseInput(input, *inputFormat)
		if data == nil {
			return
		}

		query, err := gojq.Parse(expr)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}

		iter := query.Run(data)
		for {
			v, ok := iter.Next()
			if !ok {
				break
			}
			if err, ok := v.(error); ok {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				continue
			}
			hasMatch = true
			outputValue(v)
		}
	} else {
		// Read from files
		for _, file := range files {
			content, err := os.ReadFile(file)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				continue
			}

			// For multiple documents in YAML
			decoder := yaml.NewDecoder(bytes.NewReader(content))
			firstDoc := true
			for {
				var data interface{}
				err := decoder.Decode(&data)
				if err == io.EOF {
					break
				}
				if err != nil {
					fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					break
				}

				if data == nil {
					continue
				}

				// Print document separator
				if !firstDoc && !*noDoc && isYAMLOutput() {
					fmt.Println("---")
				}
				firstDoc = false

				query, err := gojq.Parse(expr)
				if err != nil {
					fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					os.Exit(1)
				}

				iter := query.Run(data)
				for {
					v, ok := iter.Next()
					if !ok {
						break
					}
					if err, ok := v.(error); ok {
						fmt.Fprintf(os.Stderr, "Error: %v\n", err)
						continue
					}
					hasMatch = true
					outputValue(v)
				}
			}
		}
	}

	if *exitStatus && !hasMatch {
		fmt.Fprintf(os.Stderr, "Error: no matches found\n")
		os.Exit(1)
	}
}

func handleEvalAll(expr string, files []string) {
	var allData []interface{}

	if *nullInput {
		// Just evaluate with null input
		query, err := gojq.Parse(expr)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}

		iter := query.Run(nil)
		for {
			v, ok := iter.Next()
			if !ok {
				break
			}
			if err, ok := v.(error); ok {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				continue
			}
			outputValue(v)
		}
	} else if len(files) == 0 {
		// Read from stdin
		scanner := bufio.NewScanner(os.Stdin)
		var input []byte
		for scanner.Scan() {
			input = append(input, scanner.Bytes()...)
			input = append(input, '\n')
		}

		data := parseInput(input, *inputFormat)
		if data != nil {
			allData = append(allData, data)
		}

		if len(allData) > 0 {
			query, err := gojq.Parse(expr)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				os.Exit(1)
			}

			// For eval-all, wrap in array
			iter := query.Run(allData)
			for {
				v, ok := iter.Next()
				if !ok {
					break
				}
				if err, ok := v.(error); ok {
					fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					continue
				}
				outputValue(v)
			}
		}
	} else {
		// Read from files
		for _, file := range files {
			content, err := os.ReadFile(file)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				continue
			}

			decoder := yaml.NewDecoder(bytes.NewReader(content))
			for {
				var data interface{}
				err := decoder.Decode(&data)
				if err == io.EOF {
					break
				}
				if err != nil {
					fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					break
				}

				if data != nil {
					allData = append(allData, data)
				}
			}
		}

		if len(allData) > 0 {
			query, err := gojq.Parse(expr)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				os.Exit(1)
			}

			iter := query.Run(allData)
			for {
				v, ok := iter.Next()
				if !ok {
					break
				}
				if err, ok := v.(error); ok {
					fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					continue
				}
				outputValue(v)
			}
		}
	}
}

func handleCompletion(args []string) {
	fmt.Println("completion not yet implemented")
}

func parseInput(data []byte, format string) interface{} {
	// Trim whitespace
	data = bytes.TrimSpace(data)
	if len(data) == 0 {
		return nil
	}

	// Auto-detect format
	if format == "auto" || format == "a" {
		format = detectFormat(data)
	}

	// Normalize format strings
	switch format {
	case "yaml", "y", "kyaml", "ky":
		return parseYAML(data)
	case "json", "j":
		return parseJSON(data)
	case "base64":
		return parseBase64(data)
	case "uri":
		return parseURI(data)
	case "csv", "c":
		return parseCSV(data)
	case "tsv", "t":
		return parseTSV(data)
	default:
		return parseYAML(data)
	}
}

func detectFormat(data []byte) string {
	str := string(data)
	if len(str) == 0 {
		return "yaml"
	}

	first := strings.TrimSpace(str[:1])
	if first == "{" || first == "[" {
		return "json"
	}
	return "yaml"
}

func parseYAML(data []byte) interface{} {
	var result interface{}
	err := yaml.Unmarshal(data, &result)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}
	return result
}

func parseJSON(data []byte) interface{} {
	var result interface{}
	err := json.Unmarshal(data, &result)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}
	return result
}

func parseBase64(data []byte) interface{} {
	decoded, err := base64.StdEncoding.DecodeString(string(bytes.TrimSpace(data)))
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}
	return string(decoded)
}

func parseURI(data []byte) interface{} {
	decoded, err := url.QueryUnescape(string(bytes.TrimSpace(data)))
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}
	return decoded
}

func parseCSV(data []byte) interface{} {
	reader := csv.NewReader(bytes.NewReader(data))
	reader.Comma = rune((*csvSeparator)[0])
	records, err := reader.ReadAll()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}

	result := make([]interface{}, len(records))
	for i, record := range records {
		row := make([]interface{}, len(record))
		for j, field := range record {
			row[j] = field
		}
		result[i] = row
	}
	return result
}

func parseTSV(data []byte) interface{} {
	reader := csv.NewReader(bytes.NewReader(data))
	reader.Comma = '\t'
	records, err := reader.ReadAll()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}

	result := make([]interface{}, len(records))
	for i, record := range records {
		row := make([]interface{}, len(record))
		for j, field := range record {
			row[j] = field
		}
		result[i] = row
	}
	return result
}

func outputValue(v interface{}) {
	outFormat := *outputFormat
	if outFormat == "auto" || outFormat == "a" {
		outFormat = "yaml"
	}

	var output string
	switch outFormat {
	case "json", "j":
		output = toJSON(v)
	case "yaml", "y", "kyaml", "ky":
		output = toYAML(v)
	case "base64":
		output = toBase64(v)
	case "uri":
		output = toURI(v)
	case "csv", "c":
		output = toCSV(v)
	case "tsv", "t":
		output = toTSV(v)
	case "shell", "s":
		output = toShell(v)
	case "props", "p":
		output = toProperties(v)
	case "ini", "i":
		output = toINI(v)
	case "lua", "l":
		output = toLua(v)
	default:
		output = toYAML(v)
	}

	separator := "\n"
	if *nulOutput {
		separator = "\x00"
	}

	if *unwrapScalar {
		if str, ok := v.(string); ok {
			fmt.Print(str)
			fmt.Print(separator)
			return
		}
		if num, ok := v.(float64); ok {
			if num == float64(int64(num)) {
				fmt.Print(int64(num))
			} else {
				fmt.Print(num)
			}
			fmt.Print(separator)
			return
		}
		if b, ok := v.(bool); ok {
			if b {
				fmt.Print("true")
			} else {
				fmt.Print("false")
			}
			fmt.Print(separator)
			return
		}
		if v == nil {
			fmt.Print("null")
			fmt.Print(separator)
			return
		}
	}

	fmt.Print(output)
	fmt.Print(separator)
}

func toJSON(v interface{}) string {
	data, _ := json.MarshalIndent(v, "", strings.Repeat(" ", *indent))
	return string(data)
}

func toYAML(v interface{}) string {
	data, _ := yaml.Marshal(v)
	return string(bytes.TrimSuffix(data, []byte("\n")))
}

func toBase64(v interface{}) string {
	str := toString(v)
	return base64.StdEncoding.EncodeToString([]byte(str))
}

func toURI(v interface{}) string {
	str := toString(v)
	return url.QueryEscape(str)
}

func toString(v interface{}) string {
	switch val := v.(type) {
	case string:
		return val
	case float64:
		if val == float64(int64(val)) {
			return strconv.FormatInt(int64(val), 10)
		}
		return fmt.Sprintf("%v", val)
	case bool:
		if val {
			return "true"
		}
		return "false"
	case nil:
		return "null"
	default:
		data, _ := json.Marshal(val)
		return string(data)
	}
}

func toCSV(v interface{}) string {
	var buf bytes.Buffer
	writer := csv.NewWriter(&buf)
	writer.Comma = rune((*csvSeparator)[0])

	if arr, ok := v.([]interface{}); ok {
		for _, item := range arr {
			if row, ok := item.([]interface{}); ok {
				record := make([]string, len(row))
				for i, val := range row {
					record[i] = toString(val)
				}
				writer.Write(record)
			}
		}
	}
	writer.Flush()
	return strings.TrimSuffix(buf.String(), "\n")
}

func toTSV(v interface{}) string {
	var buf bytes.Buffer
	writer := csv.NewWriter(&buf)
	writer.Comma = '\t'

	if arr, ok := v.([]interface{}); ok {
		for _, item := range arr {
			if row, ok := item.([]interface{}); ok {
				record := make([]string, len(row))
				for i, val := range row {
					record[i] = toString(val)
				}
				writer.Write(record)
			}
		}
	}
	writer.Flush()
	return strings.TrimSuffix(buf.String(), "\n")
}

func toShell(v interface{}) string {
	// Simple shell output
	return toString(v)
}

func toProperties(v interface{}) string {
	// Simple properties output
	if m, ok := v.(map[string]interface{}); ok {
		var lines []string
		for k, val := range m {
			lines = append(lines, k+*propertiesSep+toString(val))
		}
		return strings.Join(lines, "\n")
	}
	return toString(v)
}

func toINI(v interface{}) string {
	// Simple INI output
	if m, ok := v.(map[string]interface{}); ok {
		var lines []string
		for k, val := range m {
			lines = append(lines, k+*propertiesSep+toString(val))
		}
		return strings.Join(lines, "\n")
	}
	return toString(v)
}

func toLua(v interface{}) string {
	output := *luaPrefix + toLuaValue(v, 0) + *luaSuffix
	return strings.TrimSuffix(output, "\n")
}

func toLuaValue(v interface{}, depth int) string {
	switch val := v.(type) {
	case map[string]interface{}:
		var pairs []string
		for k, v := range val {
			key := k
			if !*luaUnquoted {
				key = strconv.Quote(k)
			}
			pairs = append(pairs, fmt.Sprintf("%s=%v", key, toLuaValue(v, depth+1)))
		}
		return "{" + strings.Join(pairs, ",") + "}"
	case []interface{}:
		var items []string
		for _, item := range val {
			items = append(items, toLuaValue(item, depth+1))
		}
		return "{" + strings.Join(items, ",") + "}"
	case string:
		return strconv.Quote(val)
	default:
		return toString(val)
	}
}

func isYAMLOutput() bool {
	outFormat := *outputFormat
	if outFormat == "auto" || outFormat == "a" || outFormat == "yaml" || outFormat == "y" || outFormat == "kyaml" || outFormat == "ky" || outFormat == "" {
		return true
	}
	return false
}

