func handleEval(expr string, files []string) {
	hasMatch := false

	if *nullInput {
		// Parse the expression and evaluate with null input
		query, err := gojq.Parse(expr)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}

		iter := query.Run(nil)
		for {
			v, ok := iter.Next()
			if !ok {
				break
			}
			if err, ok := v.(error); ok {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				continue
			}
			hasMatch = true
			outputValue(v)
		}
	} else if len(files) == 0 {
		// Read from stdin
		scanner := bufio.NewScanner(os.Stdin)
		var input []byte
		for scanner.Scan() {
			input = append(input, scanner.Bytes()...)
			input = append(input, '\n')
		}

		data := parseInput(input, *inputFormat)
		if data == nil {
			return
		}

		query, err := gojq.Parse(expr)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}

		iter := query.Run(data)
		for {
			v, ok := iter.Next()
			if !ok {
				break
			}
			if err, ok := v.(error); ok {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				continue
			}
			hasMatch = true
			outputValue(v)
		}
	} else {
		// Read from files
		for _, file := range files {
			content, err := os.ReadFile(file)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				continue
			}

			// For multiple documents in YAML
			decoder := yaml.NewDecoder(bytes.NewReader(content))
			firstDoc := true
			for {
				var data interface{}
				err := decoder.Decode(&data)
				if err == io.EOF {
					break
				}
				if err != nil {
					fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					break
				}

				if data == nil {
					continue
				}

				// Print document separator
				if !firstDoc && !*noDoc && isYAMLOutput() {
					fmt.Println("---")
				}
				firstDoc = false

				query, err := gojq.Parse(expr)
				if err != nil {
					fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					os.Exit(1)
				}

				iter := query.Run(data)
				for {
					v, ok := iter.Next()
					if !ok {
						break
					}
					if err, ok := v.(error); ok {
						fmt.Fprintf(os.Stderr, "Error: %v\n", err)
						continue
					}
					hasMatch = true
					outputValue(v)
				}
			}
		}
	}

	if *exitStatus && !hasMatch {
		fmt.Fprintf(os.Stderr, "Error: no matches found\n")
		os.Exit(1)
	}
}

func handleEvalAll(expr string, files []string) {
	var allData []interface{}

	if *nullInput {
		// Just evaluate with null input
		query, err := gojq.Parse(expr)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}

		iter := query.Run(nil)
		for {
			v, ok := iter.Next()
			if !ok {
				break
			}
			if err, ok := v.(error); ok {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				continue
			}
			outputValue(v)
		}
	} else if len(files) == 0 {
		// Read from stdin
		scanner := bufio.NewScanner(os.Stdin)
		var input []byte
		for scanner.Scan() {
			input = append(input, scanner.Bytes()...)
			input = append(input, '\n')
		}

		data := parseInput(input, *inputFormat)
		if data != nil {
			allData = append(allData, data)
		}

		if len(allData) > 0 {
			query, err := gojq.Parse(expr)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				os.Exit(1)
			}

			// For eval-all, wrap in array
			iter := query.Run(allData)
			for {
				v, ok := iter.Next()
				if !ok {
					break
				}
				if err, ok := v.(error); ok {
					fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					continue
				}
				outputValue(v)
			}
		}
	} else {
		// Read from files
		for _, file := range files {
			content, err := os.ReadFile(file)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				continue
			}

			decoder := yaml.NewDecoder(bytes.NewReader(content))
			for {
				var data interface{}
				err := decoder.Decode(&data)
				if err == io.EOF {
					break
				}
				if err != nil {
					fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					break
				}

				if data != nil {
					allData = append(allData, data)
				}
			}
		}

		if len(allData) > 0 {
			query, err := gojq.Parse(expr)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				os.Exit(1)
			}

			iter := query.Run(allData)
			for {
				v, ok := iter.Next()
				if !ok {
					break
				}
				if err, ok := v.(error); ok {
					fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					continue
				}
				outputValue(v)
			}
		}
	}
}

