func parseInput(data []byte, format string) interface{} {
	// Trim whitespace
	data = bytes.TrimSpace(data)
	if len(data) == 0 {
		return nil
	}

	// Auto-detect format
	if format == "auto" || format == "a" {
		format = detectFormat(data)
	}

	// Normalize format strings
	switch format {
	case "yaml", "y", "kyaml", "ky":
		return parseYAML(data)
	case "json", "j":
		return parseJSON(data)
	case "base64":
		return parseBase64(data)
	case "uri":
		return parseURI(data)
	case "csv", "c":
		return parseCSV(data)
	case "tsv", "t":
		return parseTSV(data)
	default:
		return parseYAML(data)
	}
}

func detectFormat(data []byte) string {
	str := string(data)
	if len(str) == 0 {
		return "yaml"
	}

	first := strings.TrimSpace(str[:1])
	if first == "{" || first == "[" {
		return "json"
	}
	return "yaml"
}

func parseYAML(data []byte) interface{} {
	var result interface{}
	err := yaml.Unmarshal(data, &result)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}
	return result
}

func parseJSON(data []byte) interface{} {
	var result interface{}
	err := json.Unmarshal(data, &result)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}
	return result
}

func parseBase64(data []byte) interface{} {
	decoded, err := base64.StdEncoding.DecodeString(string(bytes.TrimSpace(data)))
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}
	return string(decoded)
}

func parseURI(data []byte) interface{} {
	decoded, err := url.QueryUnescape(string(bytes.TrimSpace(data)))
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}
	return decoded
}

func parseCSV(data []byte) interface{} {
	reader := csv.NewReader(bytes.NewReader(data))
	reader.Comma = rune((*csvSeparator)[0])
	records, err := reader.ReadAll()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}

	result := make([]interface{}, len(records))
	for i, record := range records {
		row := make([]interface{}, len(record))
		for j, field := range record {
			row[j] = field
		}
		result[i] = row
	}
	return result
}

func parseTSV(data []byte) interface{} {
	reader := csv.NewReader(bytes.NewReader(data))
	reader.Comma = '\t'
	records, err := reader.ReadAll()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}

	result := make([]interface{}, len(records))
	for i, record := range records {
		row := make([]interface{}, len(record))
		for j, field := range record {
			row[j] = field
		}
		result[i] = row
	}
	return result
}

func evaluateExpression(expr string, data interface{}) []interface{} {
	expr = strings.TrimSpace(expr)
	if expr == "." {
		return []interface{}{data}
	}

	if expr == "keys" {
		return getKeys(data)
	}

	if expr == "length" {
		return getLength(data)
	}

	if strings.HasPrefix(expr, ".") {
		return getPath(data, expr)
	}

	if strings.HasPrefix(expr, "[") {
		return getPath(data, "."+expr)
	}

	// Handle arithmetic and other operations
	if strings.Contains(expr, "+") || strings.Contains(expr, "-") || strings.Contains(expr, "*") || strings.Contains(expr, "/") {
		return evaluateArithmetic(expr, data)
	}

	// Handle pipe operations
	if strings.Contains(expr, "|") {
		return evaluatePipe(expr, data)
	}

	// Handle select
	if strings.HasPrefix(expr, "select(") {
		return evaluateSelect(expr, data)
	}

	// Handle map
	if strings.HasPrefix(expr, "map(") {
		return evaluateMap(expr, data)
	}

	return []interface{}{data}
}

func getKeys(data interface{}) []interface{} {
	if m, ok := data.(map[string]interface{}); ok {
		var keys []string
		for k := range m {
			keys = append(keys, k)
		}
		result := make([]interface{}, len(keys))
		for i, k := range keys {
			result[i] = k
		}
		return []interface{}{result}
	}
	if arr, ok := data.([]interface{}); ok {
		result := make([]interface{}, len(arr))
		for i := range arr {
			result[i] = float64(i)
		}
		return []interface{}{result}
	}
	return []interface{}{nil}
}

func getLength(data interface{}) []interface{} {
	switch v := data.(type) {
	case string:
		return []interface{}{float64(len(v))}
	case []interface{}:
		return []interface{}{float64(len(v))}
	case map[string]interface{}:
		return []interface{}{float64(len(v))}
	default:
		return []interface{}{nil}
	}
}

func getPath(data interface{}, path string) []interface{} {
	if path == "." {
		return []interface{}{data}
	}

	path = strings.TrimPrefix(path, ".")
	if path == "" {
		return []interface{}{data}
	}

	parts := strings.Split(path, ".")
	current := data

	for _, part := range parts {
		if part == "" {
			continue
		}

		// Handle array access like [0] or []
		if strings.HasPrefix(part, "[") {
			idx := strings.TrimSuffix(strings.TrimPrefix(part, "["), "]")
			if idx == "" {
				// Expand array
				if arr, ok := current.([]interface{}); ok {
					return arr
				}
				return []interface{}{nil}
			}

			// Parse index
			i, err := strconv.Atoi(idx)
			if err != nil {
				return []interface{}{nil}
			}

			if arr, ok := current.([]interface{}); ok {
				if i >= 0 && i < len(arr) {
					current = arr[i]
				} else {
					return []interface{}{nil}
				}
			}
			continue
		}

		if m, ok := current.(map[string]interface{}); ok {
			if v, ok := m[part]; ok {
				current = v
			} else {
				return []interface{}{nil}
			}
		} else {
			return []interface{}{nil}
		}
	}

	return []interface{}{current}
}

func evaluateArithmetic(expr string, data interface{}) []interface{} {
	if strings.Contains(expr, "+") {
		parts := strings.Split(expr, "+")
		if len(parts) == 2 {
			left := strings.TrimSpace(parts[0])
			right := strings.TrimSpace(parts[1])

			var leftVal float64
			var rightVal float64

			if left == "." {
				if v, ok := data.(float64); ok {
					leftVal = v
				}
			} else if v, err := strconv.ParseFloat(left, 64); err == nil {
				leftVal = v
			}

			if v, err := strconv.ParseFloat(right, 64); err == nil {
				rightVal = v
			}

			return []interface{}{leftVal + rightVal}
		}
	}
	return []interface{}{data}
}

func evaluatePipe(expr string, data interface{}) []interface{} {
	parts := strings.Split(expr, "|")
	current := []interface{}{data}

	for _, part := range parts {
		part = strings.TrimSpace(part)
		var next []interface{}
		for _, val := range current {
			results := evaluateExpression(part, val)
			next = append(next, results...)
		}
		current = next
	}

	return current
}

func evaluateSelect(expr string, data interface{}) []interface{} {
	// Simple select implementation
	return []interface{}{data}
}

func evaluateMap(expr string, data interface{}) []interface{} {
	// Simple map implementation
	if arr, ok := data.([]interface{}); ok {
		// Extract inner expression
		inner := strings.TrimPrefix(strings.TrimSuffix(expr, ")"), "map(")
		result := make([]interface{}, len(arr))
		for i, item := range arr {
			results := evaluateExpression(inner, item)
			if len(results) > 0 {
				result[i] = results[0]
			}
		}
		return []interface{}{result}
	}
	return []interface{}{data}
}

func outputValue(v interface{}) {
	outFormat := *outputFormat
	if outFormat == "auto" || outFormat == "a" {
		outFormat = "yaml"
	}

	var output string
	switch outFormat {
	case "json", "j":
		output = toJSON(v)
	case "yaml", "y", "kyaml", "ky":
		output = toYAML(v)
	case "base64":
		output = toBase64(v)
	case "uri":
		output = toURI(v)
	case "csv", "c":
		output = toCSV(v)
	case "tsv", "t":
		output = toTSV(v)
	case "shell", "s":
		output = toShell(v)
	case "props", "p":
		output = toProperties(v)
	case "ini", "i":
		output = toINI(v)
	case "lua", "l":
		output = toLua(v)
	default:
		output = toYAML(v)
	}

	separator := "\n"
	if *nulOutput {
		separator = "\x00"
	}

	if *unwrapScalar {
		if str, ok := v.(string); ok {
			fmt.Print(str)
			fmt.Print(separator)
			return
		}
		if num, ok := v.(float64); ok {
			if num == float64(int64(num)) {
				fmt.Print(int64(num))
			} else {
				fmt.Print(num)
			}
			fmt.Print(separator)
			return
		}
		if b, ok := v.(bool); ok {
			if b {
				fmt.Print("true")
			} else {
				fmt.Print("false")
			}
			fmt.Print(separator)
			return
		}
		if v == nil {
			fmt.Print("null")
			fmt.Print(separator)
			return
		}
	}

	fmt.Print(output)
	fmt.Print(separator)
}

func toJSON(v interface{}) string {
	data, _ := json.MarshalIndent(v, "", strings.Repeat(" ", *indent))
	return string(data)
}

func toYAML(v interface{}) string {
	data, _ := yaml.Marshal(v)
	return string(bytes.TrimSuffix(data, []byte("\n")))
}

func toBase64(v interface{}) string {
	str := toString(v)
	return base64.StdEncoding.EncodeToString([]byte(str))
}

func toURI(v interface{}) string {
	str := toString(v)
	return url.QueryEscape(str)
}

func toString(v interface{}) string {
	switch val := v.(type) {
	case string:
		return val
	case float64:
		if val == float64(int64(val)) {
			return strconv.FormatInt(int64(val), 10)
		}
		return fmt.Sprintf("%v", val)
	case bool:
		if val {
			return "true"
		}
		return "false"
	case nil:
		return "null"
	default:
		data, _ := json.Marshal(val)
		return string(data)
	}
}

func toCSV(v interface{}) string {
	var buf bytes.Buffer
	writer := csv.NewWriter(&buf)
	writer.Comma = rune((*csvSeparator)[0])

	if arr, ok := v.([]interface{}); ok {
		for _, item := range arr {
			if row, ok := item.([]interface{}); ok {
				record := make([]string, len(row))
				for i, val := range row {
					record[i] = toString(val)
				}
				writer.Write(record)
			}
		}
	}
	writer.Flush()
	return strings.TrimSuffix(buf.String(), "\n")
}

func toTSV(v interface{}) string {
	var buf bytes.Buffer
	writer := csv.NewWriter(&buf)
	writer.Comma = '\t'

	if arr, ok := v.([]interface{}); ok {
		for _, item := range arr {
			if row, ok := item.([]interface{}); ok {
				record := make([]string, len(row))
				for i, val := range row {
					record[i] = toString(val)
				}
				writer.Write(record)
			}
		}
	}
	writer.Flush()
	return strings.TrimSuffix(buf.String(), "\n")
}

func toShell(v interface{}) string {
	return toString(v)
}

func toProperties(v interface{}) string {
	if m, ok := v.(map[string]interface{}); ok {
		var lines []string
		for k, val := range m {
			lines = append(lines, k+*propertiesSep+toString(val))
		}
		return strings.Join(lines, "\n")
	}
	return toString(v)
}

func toINI(v interface{}) string {
	if m, ok := v.(map[string]interface{}); ok {
		var lines []string
		for k, val := range m {
			lines = append(lines, k+*propertiesSep+toString(val))
		}
		return strings.Join(lines, "\n")
	}
	return toString(v)
}

func toLua(v interface{}) string {
	output := *luaPrefix + toLuaValue(v, 0) + *luaSuffix
	return strings.TrimSuffix(output, "\n")
}

func toLuaValue(v interface{}, depth int) string {
	switch val := v.(type) {
	case map[string]interface{}:
		var pairs []string
		for k, v := range val {
			key := k
			if !*luaUnquoted {
				key = strconv.Quote(k)
			}
			pairs = append(pairs, fmt.Sprintf("%s=%v", key, toLuaValue(v, depth+1)))
		}
		return "{" + strings.Join(pairs, ",") + "}"
	case []interface{}:
		var items []string
		for _, item := range val {
			items = append(items, toLuaValue(item, depth+1))
		}
		return "{" + strings.Join(items, ",") + "}"
	case string:
		return strconv.Quote(val)
	default:
		return toString(val)
	}
}

func isYAMLOutput() bool {
	outFormat := *outputFormat
	if outFormat == "auto" || outFormat == "a" || outFormat == "yaml" || outFormat == "y" || outFormat == "kyaml" || outFormat == "ky" || outFormat == "" {
		return true
	}
	return false
}

