package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

// SimpleYAMLParser provides basic YAML parsing without external dependencies
type SimpleYAMLParser struct {
	content []byte
	pos     int
	line    int
	col     int
}

// ParseYAMLSimple parses YAML content without external dependencies
func ParseYAMLSimple(data []byte) interface{} {
	parser := &SimpleYAMLParser{
		content: data,
		pos:     0,
		line:    1,
		col:     0,
	}
	return parser.parse()
}

func (p *SimpleYAMLParser) parse() interface{} {
	p.skipWhitespaceAndComments()

	if p.pos >= len(p.content) {
		return nil
	}

	return p.parseValue(0)
}

func (p *SimpleYAMLParser) parseValue(indent int) interface{} {
	p.skipWhitespaceAndComments()

	if p.pos >= len(p.content) {
		return nil
	}

	// Check for array
	if p.peek() == '-' && (p.pos+1 >= len(p.content) || p.content[p.pos+1] == ' ' || p.content[p.pos+1] == '\n') {
		return p.parseArray(indent)
	}

	// Check for object/mapping
	if p.isAtKeyStart() {
		return p.parseObject(indent)
	}

	// Parse scalar
	return p.parseScalar()
}

func (p *SimpleYAMLParser) parseArray(parentIndent int) []interface{} {
	result := []interface{}{}

	for p.pos < len(p.content) {
		p.skipWhitespaceAndComments()

		if p.pos >= len(p.content) {
			break
		}

		// Check indentation
		indent := p.getIndent()
		if indent <= parentIndent && p.peek() == '-' {
			// Wrong indentation level for array item
			break
		}

		if p.peek() != '-' {
			break
		}

		p.pos++ // consume '-'
		p.skipWhitespace()

		// Get the value after the dash
		value := p.parseValue(indent + 1)
		result = append(result, value)

		// Skip to next line
		p.skipToNextLine()
	}

	return result
}

func (p *SimpleYAMLParser) parseObject(parentIndent int) map[string]interface{} {
	result := make(map[string]interface{})

	for p.pos < len(p.content) {
		p.skipWhitespaceAndComments()

		if p.pos >= len(p.content) {
			break
		}

		indent := p.getIndent()
		if indent < parentIndent {
			break
		}

		if !p.isAtKeyStart() {
			break
		}

		// Parse key
		key := p.parseKey()
		if key == "" {
			break
		}

		p.skipWhitespace()

		// Check for colon
		if p.pos >= len(p.content) || p.peek() != ':' {
			break
		}

		p.pos++ // consume ':'
		p.skipWhitespace()

		// Parse value
		if p.pos >= len(p.content) {
			result[key] = nil
			p.skipToNextLine()
			continue
		}

		if p.peek() == '\n' {
			// Value is on next line
			p.skipToNextLine()
			p.skipWhitespaceAndComments()
			nextIndent := p.getIndent()
			if nextIndent > indent {
				result[key] = p.parseValue(nextIndent)
			} else {
				result[key] = nil
			}
		} else if p.peek() == '-' && (p.pos+1 >= len(p.content) || p.content[p.pos+1] == ' ') {
			// Value is an array
			result[key] = p.parseArray(indent + 1)
		} else {
			// Value is inline
			result[key] = p.parseScalar()
			p.skipToNextLine()
		}
	}

	return result
}

func (p *SimpleYAMLParser) parseKey() string {
	start := p.pos
	for p.pos < len(p.content) && p.content[p.pos] != ':' && p.content[p.pos] != '\n' {
		p.pos++
	}
	return strings.TrimSpace(string(p.content[start:p.pos]))
}

func (p *SimpleYAMLParser) parseScalar() interface{} {
	start := p.pos

	// Find the end of the scalar
	for p.pos < len(p.content) && p.content[p.pos] != '\n' {
		p.pos++
	}

	scalar := strings.TrimSpace(string(p.content[start:p.pos]))

	// Try to parse as specific types
	if scalar == "" || scalar == "null" || scalar == "~" {
		return nil
	}

	if scalar == "true" {
		return true
	}

	if scalar == "false" {
		return false
	}

	// Try number
	if num, err := strconv.ParseFloat(scalar, 64); err == nil {
		return num
	}

	// String with quotes
	if (strings.HasPrefix(scalar, "\"") && strings.HasSuffix(scalar, "\"")) ||
		(strings.HasPrefix(scalar, "'") && strings.HasSuffix(scalar, "'")) {
		return strings.TrimPrefix(strings.TrimSuffix(scalar, "\""), "\"")
	}

	return scalar
}

func (p *SimpleYAMLParser) skipWhitespace() {
	for p.pos < len(p.content) && (p.content[p.pos] == ' ' || p.content[p.pos] == '\t') {
		p.pos++
		p.col++
	}
}

func (p *SimpleYAMLParser) skipWhitespaceAndComments() {
	for p.pos < len(p.content) {
		if p.content[p.pos] == ' ' || p.content[p.pos] == '\t' {
			p.pos++
			p.col++
		} else if p.content[p.pos] == '#' {
			// Skip comment
			for p.pos < len(p.content) && p.content[p.pos] != '\n' {
				p.pos++
			}
		} else if p.content[p.pos] == '\n' {
			p.skipToNextLine()
		} else {
			break
		}
	}
}

func (p *SimpleYAMLParser) skipToNextLine() {
	for p.pos < len(p.content) && p.content[p.pos] != '\n' {
		p.pos++
	}
	if p.pos < len(p.content) && p.content[p.pos] == '\n' {
		p.pos++
		p.line++
		p.col = 0
	}
}

func (p *SimpleYAMLParser) peek() byte {
	if p.pos < len(p.content) {
		return p.content[p.pos]
	}
	return 0
}

func (p *SimpleYAMLParser) getIndent() int {
	// Count spaces at current line start
	lineStart := p.pos
	for lineStart > 0 && p.content[lineStart-1] != '\n' {
		lineStart--
	}

	indent := 0
	for i := lineStart; i < p.pos && i < len(p.content) && p.content[i] == ' ' {
		indent++
	}
	return indent
}

func (p *SimpleYAMLParser) isAtKeyStart() bool {
	if p.pos >= len(p.content) {
		return false
	}

	ch := p.content[p.pos]
	// Key can start with letter, number, or special chars (but not -)
	return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
		(ch >= '0' && ch <= '9') || ch == '_' || ch == '-' || ch == '"' || ch == '\''
}

// Better YAML parser using regex-like approach
func ParseYAMLBetter(data []byte) interface{} {
	text := string(data)

	// Try parsing as JSON first (valid JSON is also valid YAML)
	var result interface{}
	if err := json.Unmarshal(data, &result); err == nil {
		return result
	}

	// Parse as YAML
	lines := strings.Split(text, "\n")
	return parseYAMLLines(lines, 0, 0)
}

func parseYAMLLines(lines []string, startIdx, baseIndent int) interface{} {
	if startIdx >= len(lines) {
		return nil
	}

	// Skip empty lines and comments
	for startIdx < len(lines) {
		trimmed := strings.TrimSpace(lines[startIdx])
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			startIdx++
		} else {
			break
		}
	}

	if startIdx >= len(lines) {
		return nil
	}

	firstLine := lines[startIdx]
	indent := getLineIndent(firstLine)

	// Check if it's an array
	if strings.HasPrefix(strings.TrimSpace(firstLine), "-") {
		return parseYAMLArray(lines, startIdx, indent)
	}

	// Check if it's an object
	if strings.Contains(firstLine, ":") {
		return parseYAMLMap(lines, startIdx, indent)
	}

	// It's a scalar
	return parseScalarValue(strings.TrimSpace(firstLine))
}

func parseYAMLArray(lines []string, startIdx, baseIndent int) []interface{} {
	result := []interface{}{}

	for i := startIdx; i < len(lines); i++ {
		line := lines[i]
		trimmed := strings.TrimSpace(line)

		// Skip empty lines
		if trimmed == "" {
			continue
		}

		indent := getLineIndent(line)

		// Check if still part of this array
		if indent < baseIndent {
			break
		}

		if strings.HasPrefix(trimmed, "-") {
			// Array item
			content := strings.TrimPrefix(trimmed, "-")
			content = strings.TrimSpace(content)

			if content == "" {
				// Complex value on next lines
				result = append(result, nil)
			} else if strings.Contains(content, ":") && !strings.HasPrefix(content, "\"") {
				// Inline map
				item := make(map[string]interface{})
				parseInlineMap(content, item)
				result = append(result, item)
			} else {
				result = append(result, parseScalarValue(content))
			}
		} else if indent > baseIndent {
			// Continuation of previous item
			if len(result) > 0 {
				// Could be nested structure
			}
		}
	}

	return result
}

func parseYAMLMap(lines []string, startIdx, baseIndent int) map[string]interface{} {
	result := make(map[string]interface{})

	for i := startIdx; i < len(lines); i++ {
		line := lines[i]
		trimmed := strings.TrimSpace(line)

		// Skip empty lines and comments
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}

		indent := getLineIndent(line)

		// Check if still part of this object
		if indent < baseIndent {
			break
		}

		if strings.Contains(trimmed, ":") && !strings.HasPrefix(trimmed, "-") {
			parts := strings.SplitN(trimmed, ":", 2)
			if len(parts) == 2 {
				key := strings.TrimSpace(parts[0])
				value := strings.TrimSpace(parts[1])

				if value == "" {
					result[key] = nil
				} else if value[0] == '[' || value[0] == '{' {
					// JSON-like value
					var val interface{}
					json.Unmarshal([]byte(value), &val)
					result[key] = val
				} else if strings.HasPrefix(value, "\"") && strings.HasSuffix(value, "\"") {
					result[key] = strings.Trim(value, "\"")
				} else {
					result[key] = parseScalarValue(value)
				}
			}
		}
	}

	return result
}

func parseInlineMap(line string, result map[string]interface{}) {
	parts := strings.Split(line, ",")
	for _, part := range parts {
		if strings.Contains(part, ":") {
			kv := strings.SplitN(part, ":", 2)
			if len(kv) == 2 {
				key := strings.TrimSpace(kv[0])
				value := strings.TrimSpace(kv[1])
				result[key] = parseScalarValue(value)
			}
		}
	}
}

func parseScalarValue(s string) interface{} {
	s = strings.TrimSpace(s)

	if s == "" || s == "null" || s == "~" {
		return nil
	}

	if s == "true" {
		return true
	}

	if s == "false" {
		return false
	}

	// Try to parse as number
	if num, err := strconv.ParseFloat(s, 64); err == nil {
		return num
	}

	// Remove quotes if present
	if (strings.HasPrefix(s, "\"") && strings.HasSuffix(s, "\"")) ||
		(strings.HasPrefix(s, "'") && strings.HasSuffix(s, "'")) {
		return strings.Trim(s, "\"'")
	}

	return s
}

func getLineIndent(line string) int {
	count := 0
	for _, ch := range line {
		if ch == ' ' {
			count++
		} else if ch == '\t' {
			count += 4
		} else {
			break
		}
	}
	return count
}

// Use standard json library which is better than our custom parser
func UnmarshalYAML(data []byte) (interface{}, error) {
	// First try JSON
	var result interface{}
	if err := json.Unmarshal(data, &result); err == nil {
		return result, nil
	}

	// Fall back to better YAML parsing
	return ParseYAMLBetter(data), nil
}

// MarshalYAML converts interface{} to YAML
func MarshalYAML(v interface{}) ([]byte, error) {
	// Simple YAML marshaling
	return marshallYAMLValue(v, 0), nil
}

func marshallYAMLValue(v interface{}, indent int) []byte {
	var buf bytes.Buffer
	prefix := strings.Repeat(" ", indent)

	switch val := v.(type) {
	case nil:
		buf.WriteString("null")

	case bool:
		if val {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}

	case float64:
		if val == float64(int64(val)) {
			fmt.Fprintf(&buf, "%d", int64(val))
		} else {
			fmt.Fprintf(&buf, "%v", val)
		}

	case string:
		buf.WriteString(val)

	case []interface{}:
		for i, item := range val {
			if i > 0 {
				buf.WriteString("\n")
				buf.WriteString(prefix)
			}
			buf.WriteString("- ")
			marshallYAMLScalar(&buf, item, indent+2)
		}

	case map[string]interface{}:
		first := true
		for key, item := range val {
			if !first {
				buf.WriteString("\n")
				buf.WriteString(prefix)
			}
			first = false
			buf.WriteString(key)
			buf.WriteString(": ")
			marshallYAMLScalar(&buf, item, indent+2)
		}

	default:
		data, _ := json.Marshal(v)
		buf.Write(data)
	}

	return buf.Bytes()
}

func marshallYAMLScalar(buf *bytes.Buffer, v interface{}, indent int) {
	switch val := v.(type) {
	case nil:
		buf.WriteString("null")
	case bool:
		if val {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
	case float64:
		if val == float64(int64(val)) {
			fmt.Fprintf(buf, "%d", int64(val))
		} else {
			fmt.Fprintf(buf, "%v", val)
		}
	case string:
		buf.WriteString(val)
	case []interface{}, map[string]interface{}:
		buf.WriteString("\n")
		prefix := strings.Repeat(" ", indent)
		buf.Write(marshallYAMLValue(val, indent))
	default:
		data, _ := json.Marshal(v)
		buf.Write(data)
	}
}
