func main() {
	flag.Parse()

	if *help {
		printHelp()
		os.Exit(0)
	}

	if *version {
		fmt.Printf("yq (https://github.com/mikefarah/yq/) version %s\n", Version)
		os.Exit(0)
	}

	args := flag.Args()

	// Determine the command
	cmd := "eval"
	exprArg := ""
	fileArgs := []string{}

	if len(args) > 0 {
		firstArg := args[0]
		if firstArg == "eval" || firstArg == "eval-all" || firstArg == "completion" || firstArg == "help" {
			cmd = firstArg
			exprArg = ""
			fileArgs = args[1:]
		} else {
			exprArg = firstArg
			fileArgs = args[1:]
		}
	}

	// Get expression
	expr := *expression
	if expr == "" {
		if *fromFile != "" {
			content, err := os.ReadFile(*fromFile)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				os.Exit(1)
			}
			expr = string(content)
		} else if exprArg != "" {
			expr = exprArg
		}
	}

	if expr == "" && !*nullInput {
		if len(fileArgs) > 0 {
			expr = fileArgs[0]
			fileArgs = fileArgs[1:]
		}
	}

	// If no files, read from stdin
	if len(fileArgs) == 0 && !*nullInput {
		fileArgs = []string{}
	}

	// Handle different commands
	switch cmd {
	case "eval-all":
		handleEvalAll(expr, fileArgs)
	case "eval":
		handleEval(expr, fileArgs)
	case "completion":
		handleCompletion(fileArgs)
	case "help":
		printHelp()
	}
}

func handleEval(expr string, files []string) {
	hasMatch := false

	if *nullInput {
		// Evaluate with null input using jq
		results := evaluateWithJQ(expr, nil)
		for _, v := range results {
			hasMatch = true
			outputValue(v)
		}
	} else if len(files) == 0 {
		// Read from stdin
		scanner := bufio.NewScanner(os.Stdin)
		var input []byte
		for scanner.Scan() {
			input = append(input, scanner.Bytes()...)
			input = append(input, '\n')
		}

		data := parseInput(input, *inputFormat)
		if data != nil {
			results := evaluateWithJQ(expr, data)
			for _, v := range results {
				hasMatch = true
				outputValue(v)
			}
		}
	} else {
		// Read from files
		for _, file := range files {
			content, err := os.ReadFile(file)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				continue
			}

			// For multiple documents in YAML, split by --- separator
			docs := bytes.Split(content, []byte("\n---\n"))
			if len(docs) == 0 {
				docs = [][]byte{content}
			}

			firstDoc := true
			for _, doc := range docs {
				doc = bytes.TrimSpace(doc)
				if len(doc) == 0 {
					continue
				}

				data := parseInput(doc, *inputFormat)
				if data == nil {
					continue
				}

				// Print document separator
				if !firstDoc && !*noDoc && isYAMLOutput() {
					fmt.Println("---")
				}
				firstDoc = false

				results := evaluateWithJQ(expr, data)
				for _, v := range results {
					hasMatch = true
					outputValue(v)
				}
			}
		}
	}

	if *exitStatus && !hasMatch {
		fmt.Fprintf(os.Stderr, "Error: no matches found\n")
		os.Exit(1)
	}
}

func handleEvalAll(expr string, files []string) {
	var allData []interface{}

	if *nullInput {
		// Just evaluate with null input
		results := evaluateWithJQ(expr, nil)
		for _, v := range results {
			outputValue(v)
		}
	} else if len(files) == 0 {
		// Read from stdin
		scanner := bufio.NewScanner(os.Stdin)
		var input []byte
		for scanner.Scan() {
			input = append(input, scanner.Bytes()...)
			input = append(input, '\n')
		}

		data := parseInput(input, *inputFormat)
		if data != nil {
			allData = append(allData, data)
		}

		if len(allData) > 0 {
			results := evaluateWithJQ(expr, allData)
			for _, v := range results {
				outputValue(v)
			}
		}
	} else {
		// Read from files
		for _, file := range files {
			content, err := os.ReadFile(file)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				continue
			}

			docs := bytes.Split(content, []byte("\n---\n"))
			if len(docs) == 0 {
				docs = [][]byte{content}
			}

			for _, doc := range docs {
				doc = bytes.TrimSpace(doc)
				if len(doc) == 0 {
					continue
				}

				data := parseInput(doc, *inputFormat)
				if data != nil {
					allData = append(allData, data)
				}
			}
		}

		if len(allData) > 0 {
			results := evaluateWithJQ(expr, allData)
			for _, v := range results {
				outputValue(v)
			}
		}
	}
}

func handleCompletion(args []string) {
	fmt.Println("completion not yet implemented")
