func parseInput(data []byte, format string) interface{} {
	// Trim whitespace
	data = bytes.TrimSpace(data)
	if len(data) == 0 {
		return nil
	}

	// Auto-detect format
	if format == "auto" || format == "a" {
		format = detectFormat(data)
	}

	// Normalize format strings
	switch format {
	case "yaml", "y", "kyaml", "ky":
		return parseYAML(data)
	case "json", "j":
		return parseJSON(data)
	case "base64":
		return parseBase64(data)
	case "uri":
		return parseURI(data)
	case "csv", "c":
		return parseCSV(data)
	case "tsv", "t":
		return parseTSV(data)
	default:
		return parseYAML(data)
	}
}

func detectFormat(data []byte) string {
	str := string(data)
	if len(str) == 0 {
		return "yaml"
	}

	first := strings.TrimSpace(str[:1])
	if first == "{" || first == "[" {
		return "json"
	}
	return "yaml"
}

func parseYAML(data []byte) interface{} {
	// Try JSON first
	var result interface{}
	if err := json.Unmarshal(data, &result); err == nil {
		return result
	}

	// Simple YAML to JSON conversion using python/jq
	jsonData := convertYAMLToJSON(data)
	if jsonData != nil {
		return jsonData
	}

	// Fallback: return as string
	return string(data)
}

func convertYAMLToJSON(yamlData []byte) interface{} {
	// Use python to convert YAML to JSON if available
	cmd := exec.Command("python3", "-c", `
import json
import sys
try:
    import yaml
    data = yaml.safe_load(sys.stdin)
    print(json.dumps(data))
except:
    import sys
    content = sys.stdin.read()
    try:
        data = json.loads(content)
        print(json.dumps(data))
    except:
        print("null")
`)
	cmd.Stdin = bytes.NewReader(yamlData)
	output, err := cmd.Output()
	if err != nil {
		return nil
	}

	var result interface{}
	if err := json.Unmarshal(bytes.TrimSpace(output), &result); err != nil {
		return nil
	}

	return result
}

func parseJSON(data []byte) interface{} {
	var result interface{}
	err := json.Unmarshal(data, &result)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}
	return result
}

func parseBase64(data []byte) interface{} {
	decoded, err := base64.StdEncoding.DecodeString(string(bytes.TrimSpace(data)))
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}
	return string(decoded)
}

func parseURI(data []byte) interface{} {
	decoded, err := url.QueryUnescape(string(bytes.TrimSpace(data)))
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}
	return decoded
}

func parseCSV(data []byte) interface{} {
	reader := csv.NewReader(bytes.NewReader(data))
	reader.Comma = rune((*csvSeparator)[0])
	records, err := reader.ReadAll()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}

	result := make([]interface{}, len(records))
	for i, record := range records {
		row := make([]interface{}, len(record))
		for j, field := range record {
			row[j] = field
		}
		result[i] = row
	}
	return result
}

func parseTSV(data []byte) interface{} {
	reader := csv.NewReader(bytes.NewReader(data))
	reader.Comma = '\t'
	records, err := reader.ReadAll()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}

	result := make([]interface{}, len(records))
	for i, record := range records {
		row := make([]interface{}, len(record))
		for j, field := range record {
			row[j] = field
		}
		result[i] = row
	}
	return result
}

func evaluateWithJQ(expr string, data interface{}) []interface{} {
	// Convert data to JSON
	jsonData, err := json.Marshal(data)
	if err != nil {
		return []interface{}{}
	}

	// Use jq to evaluate
	cmd := exec.Command("jq", "-r", expr)
	cmd.Stdin = bytes.NewReader(jsonData)
	cmd.Stderr = os.Stderr

	output, err := cmd.Output()
	if err != nil {
		// Try without -r flag for non-string results
		cmd = exec.Command("jq", expr)
		cmd.Stdin = bytes.NewReader(jsonData)
		cmd.Stderr = os.Stderr
		output, err = cmd.Output()
		if err != nil {
			return []interface{}{}
		}
	}

	// Parse output
	lines := bytes.Split(bytes.TrimSpace(output), []byte("\n"))
	results := make([]interface{}, 0)

	for _, line := range lines {
		if len(line) == 0 {
			continue
		}

		var result interface{}
		if err := json.Unmarshal(line, &result); err != nil {
			// It's a string or scalar
			results = append(results, string(line))
		} else {
			results = append(results, result)
		}
	}

	return results
}

func outputValue(v interface{}) {
	outFormat := *outputFormat
	if outFormat == "auto" || outFormat == "a" {
		outFormat = "yaml"
	}

	var output string
	switch outFormat {
	case "json", "j":
		output = toJSON(v)
	case "yaml", "y", "kyaml", "ky":
		output = toYAML(v)
	case "base64":
		output = toBase64(v)
	case "uri":
		output = toURI(v)
	case "csv", "c":
		output = toCSV(v)
	case "tsv", "t":
		output = toTSV(v)
	case "shell", "s":
		output = toShell(v)
	case "props", "p":
		output = toProperties(v)
	case "ini", "i":
		output = toINI(v)
	case "lua", "l":
		output = toLua(v)
	default:
		output = toYAML(v)
	}

	separator := "\n"
	if *nulOutput {
		separator = "\x00"
	}

	if *unwrapScalar {
		if str, ok := v.(string); ok {
			fmt.Print(str)
			fmt.Print(separator)
			return
		}
		if num, ok := v.(float64); ok {
			if num == float64(int64(num)) {
				fmt.Print(int64(num))
			} else {
				fmt.Print(num)
			}
			fmt.Print(separator)
			return
		}
		if b, ok := v.(bool); ok {
			if b {
				fmt.Print("true")
			} else {
				fmt.Print("false")
			}
			fmt.Print(separator)
			return
		}
		if v == nil {
			fmt.Print("null")
			fmt.Print(separator)
			return
		}
	}

	fmt.Print(output)
	fmt.Print(separator)
}

func toJSON(v interface{}) string {
	data, _ := json.MarshalIndent(v, "", strings.Repeat(" ", *indent))
	return string(data)
}

func toYAML(v interface{}) string {
	// Convert to JSON first, then to YAML using python
	jsonData, _ := json.Marshal(v)
	cmd := exec.Command("python3", "-c", `
import json
import sys
try:
    import yaml
    data = json.loads(sys.stdin.read())
    sys.stdout.write(yaml.dump(data, default_flow_style=False))
except:
    sys.stdout.write(sys.stdin.read())
`)
	cmd.Stdin = bytes.NewReader(jsonData)
	output, err := cmd.Output()
	if err != nil {
		// Fallback to JSON
		return string(jsonData)
	}
	return strings.TrimSuffix(string(output), "\n")
}

func toBase64(v interface{}) string {
	str := toString(v)
	return base64.StdEncoding.EncodeToString([]byte(str))
}

func toURI(v interface{}) string {
	str := toString(v)
	return url.QueryEscape(str)
}

func toString(v interface{}) string {
	switch val := v.(type) {
	case string:
		return val
	case float64:
		if val == float64(int64(val)) {
			return strconv.FormatInt(int64(val), 10)
		}
		return fmt.Sprintf("%v", val)
	case bool:
		if val {
			return "true"
		}
		return "false"
	case nil:
		return "null"
	default:
		data, _ := json.Marshal(val)
		return string(data)
	}
}

func toCSV(v interface{}) string {
	var buf bytes.Buffer
	writer := csv.NewWriter(&buf)
	writer.Comma = rune((*csvSeparator)[0])

	if arr, ok := v.([]interface{}); ok {
		for _, item := range arr {
			if row, ok := item.([]interface{}); ok {
				record := make([]string, len(row))
				for i, val := range row {
					record[i] = toString(val)
				}
				writer.Write(record)
			}
		}
	}
	writer.Flush()
	return strings.TrimSuffix(buf.String(), "\n")
}

func toTSV(v interface{}) string {
	var buf bytes.Buffer
	writer := csv.NewWriter(&buf)
	writer.Comma = '\t'

	if arr, ok := v.([]interface{}); ok {
		for _, item := range arr {
			if row, ok := item.([]interface{}); ok {
				record := make([]string, len(row))
				for i, val := range row {
					record[i] = toString(val)
				}
				writer.Write(record)
			}
		}
	}
	writer.Flush()
	return strings.TrimSuffix(buf.String(), "\n")
}

func toShell(v interface{}) string {
	return toString(v)
}

func toProperties(v interface{}) string {
	if m, ok := v.(map[string]interface{}); ok {
		var lines []string
		for k, val := range m {
			lines = append(lines, k+*propertiesSep+toString(val))
		}
		return strings.Join(lines, "\n")
	}
	return toString(v)
}

func toINI(v interface{}) string {
	if m, ok := v.(map[string]interface{}); ok {
		var lines []string
		for k, val := range m {
			lines = append(lines, k+*propertiesSep+toString(val))
		}
		return strings.Join(lines, "\n")
	}
	return toString(v)
}

func toLua(v interface{}) string {
	output := *luaPrefix + toLuaValue(v, 0) + *luaSuffix
	return strings.TrimSuffix(output, "\n")
}

func toLuaValue(v interface{}, depth int) string {
	switch val := v.(type) {
	case map[string]interface{}:
		var pairs []string
		for k, v := range val {
			key := k
			if !*luaUnquoted {
				key = strconv.Quote(k)
			}
			pairs = append(pairs, fmt.Sprintf("%s=%v", key, toLuaValue(v, depth+1)))
		}
		return "{" + strings.Join(pairs, ",") + "}"
	case []interface{}:
		var items []string
		for _, item := range val {
			items = append(items, toLuaValue(item, depth+1))
		}
		return "{" + strings.Join(items, ",") + "}"
	case string:
		return strconv.Quote(val)
	default:
		return toString(val)
	}
}

func isYAMLOutput() bool {
	outFormat := *outputFormat
	if outFormat == "auto" || outFormat == "a" || outFormat == "yaml" || outFormat == "y" || outFormat == "kyaml" || outFormat == "ky" || outFormat == "" {
		return true
	}
	return false
}

