	fileArgs := []string{}

	if len(args) > 0 {
		firstArg := args[0]
		if firstArg == "eval" || firstArg == "eval-all" || firstArg == "completion" || firstArg == "help" {
			cmd = firstArg
			exprArg = ""
			fileArgs = args[1:]
		} else {
			exprArg = firstArg
			fileArgs = args[1:]
		}
	}

	// Get expression
	expr := *expression
	if expr == "" {
		if *fromFile != "" {
			content, err := os.ReadFile(*fromFile)
			if err != nil {
