func parseInput(data []byte, format string) interface{} {
	data = bytes.TrimSpace(data)
	if len(data) == 0 {
		return nil
	}

	if format == "auto" || format == "a" {
		format = detectFormat(data)
	}

	switch format {
	case "yaml", "y", "kyaml", "ky":
		return parseYAML(data)
	case "json", "j":
		return parseJSON(data)
	case "base64":
		return parseBase64(data)
	case "uri":
		return parseURI(data)
	case "csv", "c":
		return parseCSV(data)
	case "tsv", "t":
		return parseTSV(data)
	default:
		return parseYAML(data)
	}
}

func detectFormat(data []byte) string {
	str := string(data)
	if len(str) == 0 {
		return "yaml"
	}

	first := strings.TrimSpace(str[:1])
	if first == "{" || first == "[" {
		return "json"
	}
	return "yaml"
}

func parseYAML(data []byte) interface{} {
	var result interface{}
	if err := json.Unmarshal(data, &result); err == nil {
		return result
	}

	// Try to convert YAML to JSON
	jsonData := convertYAMLToJSON(data)
	if jsonData != nil {
		return jsonData
	}

	return string(data)
}

func convertYAMLToJSON(yamlData []byte) interface{} {
	cmd := exec.Command("python3", "-c", `
import json
import sys
try:
    import yaml
    data = yaml.safe_load(sys.stdin)
    print(json.dumps(data))
except:
    import sys
    content = sys.stdin.read()
    try:
        data = json.loads(content)
        print(json.dumps(data))
    except:
        print("null")
`)
	cmd.Stdin = bytes.NewReader(yamlData)
	output, err := cmd.Output()
	if err != nil {
		return nil
	}

	var result interface{}
	if err := json.Unmarshal(bytes.TrimSpace(output), &result); err != nil {
		return nil
	}

	return result
}

