func handleEval(expr string, files []string) {
	hasMatch := false

	if *nullInput {
		// Evaluate with null input using jq
		results := evaluateWithJQ(expr, nil)
		for _, v := range results {
			hasMatch = true
			outputValue(v)
		}
	} else if len(files) == 0 {
		// Read from stdin
		scanner := bufio.NewScanner(os.Stdin)
		var input []byte
		for scanner.Scan() {
			input = append(input, scanner.Bytes()...)
			input = append(input, '\n')
		}

		data := parseInput(input, *inputFormat)
		if data != nil {
			results := evaluateWithJQ(expr, data)
			for _, v := range results {
				hasMatch = true
				outputValue(v)
			}
		}
	} else {
		// Read from files
		for _, file := range files {
			content, err := os.ReadFile(file)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				continue
			}

			// For multiple documents in YAML, split by --- separator
			docs := bytes.Split(content, []byte("\n---\n"))
			if len(docs) == 0 {
				docs = [][]byte{content}
			}

			firstDoc := true
			for _, doc := range docs {
				doc = bytes.TrimSpace(doc)
				if len(doc) == 0 {
					continue
				}

				data := parseInput(doc, *inputFormat)
				if data == nil {
					continue
				}

				// Print document separator
				if !firstDoc && !*noDoc && isYAMLOutput() {
					fmt.Println("---")
				}
				firstDoc = false

				results := evaluateWithJQ(expr, data)
				for _, v := range results {
					hasMatch = true
					outputValue(v)
				}
			}
		}
	}

	if *exitStatus && !hasMatch {
		fmt.Fprintf(os.Stderr, "Error: no matches found\n")
		os.Exit(1)
	}
}

