package main

import (
	"bytes"
	"encoding/json"
	"strconv"
	"strings"
)

// SimpleYAMLParser is a basic YAML parser for common cases
func ParseSimpleYAML(data []byte) interface{} {
	lines := strings.Split(string(data), "\n")
	return parseYAMLLines(lines, 0)
}

func parseYAMLLines(lines []string, baseIndent int) interface{} {
	lines = skipEmptyLines(lines)
	if len(lines) == 0 {
		return nil
	}

	// Check if first line is an array
	firstLine := strings.TrimSpace(lines[0])
	if strings.HasPrefix(firstLine, "-") {
		return parseYAMLArray(lines, baseIndent)
	}

	// Check if it's a map
	if strings.Contains(firstLine, ":") {
		return parseYAMLMap(lines, baseIndent)
	}

	// Scalar value
	return parseScalarValue(firstLine)
}

func parseYAMLArray(lines []string, baseIndent int) []interface{} {
	result := []interface{}{}

	for i := 0; i < len(lines); i++ {
		line := lines[i]
		trimmed := strings.TrimSpace(line)

		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}

		indent := getIndent(line)

		if indent < baseIndent {
			break
		}

		if strings.HasPrefix(trimmed, "-") {
			content := strings.TrimPrefix(trimmed, "-")
			content = strings.TrimSpace(content)

			if content == "" {
				// Complex value on next line
				remaining := lines[i+1:]
				nextIndent := baseIndent + 2
				value := parseYAMLLines(remaining, nextIndent)
				result = append(result, value)
				// Skip processed lines
				skipCount := countProcessedLines(remaining, nextIndent)
				i += skipCount
			} else if strings.HasPrefix(content, "{") && strings.HasSuffix(content, "}") {
				// Inline JSON
				var val interface{}
				json.Unmarshal([]byte(content), &val)
				result = append(result, val)
			} else if strings.HasPrefix(content, "[") && strings.HasSuffix(content, "]") {
				// Inline JSON array
				var val interface{}
				json.Unmarshal([]byte(content), &val)
				result = append(result, val)
			} else {
				result = append(result, parseScalarValue(content))
			}
		}
	}

	return result
}

func parseYAMLMap(lines []string, baseIndent int) map[string]interface{} {
	result := make(map[string]interface{})

	for i := 0; i < len(lines); i++ {
		line := lines[i]
		trimmed := strings.TrimSpace(line)

		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}

		indent := getIndent(line)

		if indent < baseIndent {
			break
		}

		if strings.Contains(trimmed, ":") && !strings.HasPrefix(trimmed, "-") {
			parts := strings.SplitN(trimmed, ":", 2)
			if len(parts) == 2 {
				key := strings.TrimSpace(parts[0])
				value := strings.TrimSpace(parts[1])

				if value == "" {
					// Value is on next line(s)
					remaining := lines[i+1:]
					nextIndent := indent + 2
					val := parseYAMLLines(remaining, nextIndent)
					result[key] = val
					skipCount := countProcessedLines(remaining, nextIndent)
					i += skipCount
				} else if strings.HasPrefix(value, "{") && strings.HasSuffix(value, "}") {
					// Inline JSON
					var val interface{}
					json.Unmarshal([]byte(value), &val)
					result[key] = val
				} else if strings.HasPrefix(value, "[") && strings.HasSuffix(value, "]") {
					// Inline JSON array
					var val interface{}
					json.Unmarshal([]byte(value), &val)
					result[key] = val
				} else {
					result[key] = parseScalarValue(value)
				}
			}
		} else if strings.HasPrefix(trimmed, "-") {
			// Array value
			break
		}
	}

	return result
}

func parseScalarValue(s string) interface{} {
	s = strings.TrimSpace(s)

	if s == "" || s == "null" || s == "~" {
		return nil
	}

	if s == "true" {
		return true
	}

	if s == "false" {
		return false
	}

	// Try number
	if num, err := strconv.ParseFloat(s, 64); err == nil {
		return num
	}

	// Remove quotes
	if (strings.HasPrefix(s, "\"") && strings.HasSuffix(s, "\"")) ||
		(strings.HasPrefix(s, "'") && strings.HasSuffix(s, "'")) {
		return strings.Trim(s, "\"'")
	}

	return s
}

func getIndent(line string) int {
	count := 0
	for _, ch := range line {
		if ch == ' ' {
			count++
		} else {
			break
		}
	}
	return count
}

func skipEmptyLines(lines []string) []string {
	for len(lines) > 0 {
		trimmed := strings.TrimSpace(lines[0])
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			lines = lines[1:]
		} else {
			break
		}
	}
	return lines
}

func countProcessedLines(lines []string, baseIndent int) int {
	count := 0
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			count++
			continue
		}

		indent := getIndent(line)
		if indent < baseIndent {
			break
		}
		count++
	}
	return count
}

// MarshalYAML converts a value back to YAML format
func MarshalSimpleYAML(v interface{}, indent string) string {
	return marshalYAMLValue(v, "")
}

func marshalYAMLValue(v interface{}, prefix string) string {
	var buf bytes.Buffer

	switch val := v.(type) {
	case nil:
		buf.WriteString("null")

	case bool:
		if val {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}

	case float64:
		if val == float64(int64(val)) {
			buf.WriteString(strconv.FormatInt(int64(val), 10))
		} else {
			buf.WriteString(strconv.FormatFloat(val, 'f', -1, 64))
		}

	case string:
		buf.WriteString(val)

	case []interface{}:
		for i, item := range val {
			if i > 0 {
				buf.WriteString("\n")
				buf.WriteString(prefix)
			}
			buf.WriteString("- ")
			buf.WriteString(marshalYAMLValue(item, prefix+"  "))
		}

	case map[string]interface{}:
		first := true
		for key, item := range val {
			if !first {
				buf.WriteString("\n")
				buf.WriteString(prefix)
			}
			first = false
			buf.WriteString(key)
			buf.WriteString(": ")
			buf.WriteString(marshalYAMLValue(item, prefix+"  "))
		}

	default:
		data, _ := json.Marshal(v)
		buf.Write(data)
	}

	return buf.String()
}
