	"strings"
)

var (
	colors            = flag.Bool("C", false, "force print with colors")
	noColors          = flag.Bool("M", false, "force print with no colors")
	exitStatus        = flag.Bool("e", false, "set exit status if there are no matches or null or false is returned")
	help              = flag.Bool("h", false, "help for yq")
	inplace           = flag.Bool("i", false, "update the file in place of first file given")
	indent            = flag.Int("I", 2, "sets indent level for output")
	nullInput         = flag.Bool("n", false, "Don't read input, simply evaluate the expression given")
	noDoc             = flag.Bool("N", false, "Don't print document separators (---)")
	nulOutput         = flag.Bool("0", false, "Use NUL char to separate values")
	prettyPrint       = flag.Bool("P", false, "pretty print")
	unwrapScalar      = flag.Bool("r", true, "unwrap scalar")
	verbose           = flag.Bool("v", false, "verbose mode")
	version           = flag.Bool("V", false, "Print version information and quit")
	inputFormat       = flag.String("p", "auto", "parse format for input")
	outputFormat      = flag.String("o", "auto", "output format type")
	expression        = flag.String("expression", "", "forcibly set the expression argument")
	fromFile          = flag.String("from-file", "", "Load expression from specified file")
	csvSeparator      = flag.String("csv-separator", ",", "CSV Separator character")
	propertiesSep     = flag.String("properties-separator", " = ", "separator to use between keys and values")
	luaPrefix         = flag.String("lua-prefix", "return ", "prefix")
	luaSuffix         = flag.String("lua-suffix", ";\n", "suffix")
	luaUnquoted       = flag.Bool("lua-unquoted", false, "output unquoted string keys")
)

const Version = "v4.52.5"

func main() {
	flag.Parse()

	if *help {
		printHelp()
		os.Exit(0)
	}

	if *version {
		fmt.Printf("yq (https://github.com/mikefarah/yq/) version %s\n", Version)
		os.Exit(0)
	}

	args := flag.Args()

	// Determine the command
	cmd := "eval"
	exprArg := ""
	fileArgs := []string{}

	if len(args) > 0 {
		firstArg := args[0]
		if firstArg == "eval" || firstArg == "eval-all" || firstArg == "completion" || firstArg == "help" {
			cmd = firstArg
			exprArg = ""
			fileArgs = args[1:]
		} else {
			exprArg = firstArg
			fileArgs = args[1:]
		}
	}

	// Get expression
	expr := *expression
	if expr == "" {
		if *fromFile != "" {
			content, err := os.ReadFile(*fromFile)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				os.Exit(1)
			}
			expr = string(content)
		} else if exprArg != "" {
			expr = exprArg
		}
	}

	if expr == "" && !*nullInput {
		if len(fileArgs) > 0 {
			expr = fileArgs[0]
			fileArgs = fileArgs[1:]
		}
	}

	// Handle different commands
	switch cmd {
	case "eval-all":
		handleEvalAll(expr, fileArgs)
	case "eval":
		handleEval(expr, fileArgs)
	case "completion":
		handleCompletion(fileArgs)
	case "help":
		printHelp()
	}
}

func handleEval(expr string, files []string) {
	hasMatch := false

	if *nullInput {
		// Evaluate with null input using jq
		results := evaluateWithJQ(expr, nil)
		for _, v := range results {
			hasMatch = true
			outputValue(v)
		}
	} else if len(files) == 0 {
		// Read from stdin
		scanner := bufio.NewScanner(os.Stdin)
		var input []byte
		for scanner.Scan() {
			input = append(input, scanner.Bytes()...)
			input = append(input, '\n')
		}

		data := parseInput(input, *inputFormat)
		if data != nil {
			results := evaluateWithJQ(expr, data)
			for _, v := range results {
				hasMatch = true
				outputValue(v)
			}
		}
	} else {
		// Read from files
		for _, file := range files {
			content, err := os.ReadFile(file)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				continue
			}

			// For multiple documents in YAML, split by --- separator
			docs := bytes.Split(content, []byte("\n---\n"))
			if len(docs) == 0 {
				docs = [][]byte{content}
			}

			firstDoc := true
			for _, doc := range docs {
				doc = bytes.TrimSpace(doc)
				if len(doc) == 0 {
					continue
				}

				data := parseInput(doc, *inputFormat)
				if data == nil {
					continue
				}

				// Print document separator
				if !firstDoc && !*noDoc && isYAMLOutput() {
					fmt.Println("---")
				}
				firstDoc = false

				results := evaluateWithJQ(expr, data)
				for _, v := range results {
					hasMatch = true
					outputValue(v)
				}
			}
		}
	}

	if *exitStatus && !hasMatch {
		fmt.Fprintf(os.Stderr, "Error: no matches found\n")
		os.Exit(1)
	}
}

func handleEvalAll(expr string, files []string) {
	var allData []interface{}

	if *nullInput {
		results := evaluateWithJQ(expr, nil)
		for _, v := range results {
			outputValue(v)
		}
	} else if len(files) == 0 {
		scanner := bufio.NewScanner(os.Stdin)
		var input []byte
		for scanner.Scan() {
			input = append(input, scanner.Bytes()...)
			input = append(input, '\n')
		}

		data := parseInput(input, *inputFormat)
		if data != nil {
			allData = append(allData, data)
		}

		if len(allData) > 0 {
			results := evaluateWithJQ(expr, allData)
			for _, v := range results {
				outputValue(v)
			}
		}
	} else {
		for _, file := range files {
			content, err := os.ReadFile(file)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				continue
			}

			docs := bytes.Split(content, []byte("\n---\n"))
			if len(docs) == 0 {
				docs = [][]byte{content}
			}

			for _, doc := range docs {
				doc = bytes.TrimSpace(doc)
				if len(doc) == 0 {
					continue
				}

				data := parseInput(doc, *inputFormat)
				if data != nil {
					allData = append(allData, data)
				}
			}
		}

		if len(allData) > 0 {
			results := evaluateWithJQ(expr, allData)
			for _, v := range results {
				outputValue(v)
			}
		}
	}
}

func handleCompletion(args []string) {
	fmt.Println("completion not yet implemented")
}

func parseInput(data []byte, format string) interface{} {
	data = bytes.TrimSpace(data)
	if len(data) == 0 {
		return nil
	}

	if format == "auto" || format == "a" {
		format = detectFormat(data)
	}

	switch format {
	case "yaml", "y", "kyaml", "ky":
		return parseYAML(data)
	case "json", "j":
		return parseJSON(data)
	case "base64":
		return parseBase64(data)
	case "uri":
		return parseURI(data)
	case "csv", "c":
		return parseCSV(data)
	case "tsv", "t":
		return parseTSV(data)
	default:
		return parseYAML(data)
	}
}

func detectFormat(data []byte) string {
	str := string(data)
	if len(str) == 0 {
		return "yaml"
	}

	first := strings.TrimSpace(str[:1])
	if first == "{" || first == "[" {
		return "json"
	}
	return "yaml"
}

func parseYAML(data []byte) interface{} {
	// First try simple YAML parser
	yamlResult := ParseSimpleYAML(data)
	if yamlResult != nil {
		return yamlResult
	}

	// Try JSON
	var jsonResult interface{}
	if err := json.Unmarshal(data, &jsonResult); err == nil {
		return jsonResult
	}

	return string(data)
}

func parseJSON(data []byte) interface{} {
	var result interface{}
	err := json.Unmarshal(data, &result)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}
	return result
}

func parseBase64(data []byte) interface{} {
	decoded, err := base64.StdEncoding.DecodeString(string(bytes.TrimSpace(data)))
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}
	return string(decoded)
}

func parseURI(data []byte) interface{} {
	decoded, err := url.QueryUnescape(string(bytes.TrimSpace(data)))
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}
	return decoded
}

func parseCSV(data []byte) interface{} {
	reader := csv.NewReader(bytes.NewReader(data))
	reader.Comma = rune((*csvSeparator)[0])
	records, err := reader.ReadAll()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}

	result := make([]interface{}, len(records))
	for i, record := range records {
		row := make([]interface{}, len(record))
		for j, field := range record {
			row[j] = field
		}
		result[i] = row
	}
	return result
}

func parseTSV(data []byte) interface{} {
	reader := csv.NewReader(bytes.NewReader(data))
	reader.Comma = '\t'
	records, err := reader.ReadAll()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return nil
	}

	result := make([]interface{}, len(records))
	for i, record := range records {
		row := make([]interface{}, len(record))
		for j, field := range record {
			row[j] = field
		}
		result[i] = row
	}
	return result
}

func evaluateWithJQ(expr string, data interface{}) []interface{} {
	jsonData, err := json.Marshal(data)
	if err != nil {
		return []interface{}{}
	}

	cmd := exec.Command("jq", "-r", expr)
	cmd.Stdin = bytes.NewReader(jsonData)
	cmd.Stderr = os.Stderr

	output, err := cmd.Output()
	if err != nil {
		cmd = exec.Command("jq", expr)
		cmd.Stdin = bytes.NewReader(jsonData)
		cmd.Stderr = os.Stderr
		output, err = cmd.Output()
		if err != nil {
			return []interface{}{}
		}
	}

	lines := bytes.Split(bytes.TrimSpace(output), []byte("\n"))
	results := make([]interface{}, 0)

	for _, line := range lines {
		if len(line) == 0 {
			continue
		}

		var result interface{}
		if err := json.Unmarshal(line, &result); err != nil {
			results = append(results, string(line))
		} else {
			results = append(results, result)
		}
	}

	return results
}

func outputValue(v interface{}) {
	outFormat := *outputFormat
	if outFormat == "auto" || outFormat == "a" {
		outFormat = "yaml"
	}

	var output string
	switch outFormat {
	case "json", "j":
		output = toJSON(v)
	case "yaml", "y", "kyaml", "ky":
		output = toYAML(v)
	case "base64":
		output = toBase64(v)
	case "uri":
		output = toURI(v)
	case "csv", "c":
		output = toCSV(v)
	case "tsv", "t":
		output = toTSV(v)
	case "shell", "s":
		output = toShell(v)
	case "props", "p":
		output = toProperties(v)
	case "lua", "l":
		output = toLua(v)
	default:
		output = toYAML(v)
	}

	separator := "\n"
	if *nulOutput {
		separator = "\x00"
	}

	if *unwrapScalar {
		if str, ok := v.(string); ok {
			fmt.Print(str)
			fmt.Print(separator)
			return
		}
		if num, ok := v.(float64); ok {
			if num == float64(int64(num)) {
				fmt.Print(int64(num))
			} else {
				fmt.Print(num)
			}
			fmt.Print(separator)
			return
		}
		if b, ok := v.(bool); ok {
			if b {
				fmt.Print("true")
			} else {
				fmt.Print("false")
			}
			fmt.Print(separator)
			return
		}
		if v == nil {
			fmt.Print("null")
			fmt.Print(separator)
			return
		}
	}

	fmt.Print(output)
	fmt.Print(separator)
}

func toJSON(v interface{}) string {
	data, _ := json.MarshalIndent(v, "", strings.Repeat(" ", *indent))
	return string(data)
}

func toYAML(v interface{}) string {
	return MarshalSimpleYAML(v, "")
}

func toBase64(v interface{}) string {
	str := toString(v)
	return base64.StdEncoding.EncodeToString([]byte(str))
}

func toURI(v interface{}) string {
	str := toString(v)
	return url.QueryEscape(str)
}

func toString(v interface{}) string {
	switch val := v.(type) {
	case string:
		return val
	case float64:
		if val == float64(int64(val)) {
			return strconv.FormatInt(int64(val), 10)
		}
		return fmt.Sprintf("%v", val)
	case bool:
		if val {
			return "true"
		}
		return "false"
	case nil:
		return "null"
	default:
		data, _ := json.Marshal(val)
		return string(data)
	}
}

func toCSV(v interface{}) string {
	var buf bytes.Buffer
	writer := csv.NewWriter(&buf)
	writer.Comma = rune((*csvSeparator)[0])

	if arr, ok := v.([]interface{}); ok {
		for _, item := range arr {
			if row, ok := item.([]interface{}); ok {
				record := make([]string, len(row))
				for i, val := range row {
					record[i] = toString(val)
				}
				writer.Write(record)
			}
		}
	}
	writer.Flush()
	return strings.TrimSuffix(buf.String(), "\n")
}

func toTSV(v interface{}) string {
	var buf bytes.Buffer
	writer := csv.NewWriter(&buf)
	writer.Comma = '\t'

	if arr, ok := v.([]interface{}); ok {
		for _, item := range arr {
			if row, ok := item.([]interface{}); ok {
				record := make([]string, len(row))
				for i, val := range row {
					record[i] = toString(val)
				}
				writer.Write(record)
			}
		}
	}
	writer.Flush()
	return strings.TrimSuffix(buf.String(), "\n")
}

func toShell(v interface{}) string {
	return toString(v)
}

func toProperties(v interface{}) string {
	if m, ok := v.(map[string]interface{}); ok {
		var lines []string
		for k, val := range m {
			lines = append(lines, k+*propertiesSep+toString(val))
		}
		return strings.Join(lines, "\n")
	}
	return toString(v)
}

func toLua(v interface{}) string {
	output := *luaPrefix + toLuaValue(v, 0) + *luaSuffix
	return strings.TrimSuffix(output, "\n")
}

func toLuaValue(v interface{}, depth int) string {
	switch val := v.(type) {
	case map[string]interface{}:
		var pairs []string
		for k, v := range val {
			key := k
			if !*luaUnquoted {
				key = strconv.Quote(k)
			}
			pairs = append(pairs, fmt.Sprintf("%s=%v", key, toLuaValue(v, depth+1)))
		}
		return "{" + strings.Join(pairs, ",") + "}"
	case []interface{}:
		var items []string
		for _, item := range val {
			items = append(items, toLuaValue(item, depth+1))
		}
		return "{" + strings.Join(items, ",") + "}"
	case string:
		return strconv.Quote(val)
	default:
		return toString(val)
	}
}

func isYAMLOutput() bool {
	outFormat := *outputFormat
	if outFormat == "auto" || outFormat == "a" || outFormat == "yaml" || outFormat == "y" || outFormat == "kyaml" || outFormat == "ky" || outFormat == "" {
		return true
	}
	return false
}

