func marshalYAMLValue(v interface{}, prefix string) string {
	var buf bytes.Buffer

	switch val := v.(type) {
	case nil:
		buf.WriteString("null")
	case bool:
		if val {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
	case float64:
		if val == float64(int64(val)) {
			buf.WriteString(strconv.FormatInt(int64(val), 10))
		} else {
			buf.WriteString(strconv.FormatFloat(val, 'f', -1, 64))
		}
	case string:
		buf.WriteString(val)
	case []interface{}:
		for i, item := range val {
			if i > 0 {
				buf.WriteString("\n")
				buf.WriteString(prefix)
			}
			buf.WriteString("- ")
			buf.WriteString(marshalYAMLValue(item, prefix+"  "))
		}
	case map[string]interface{}:
		first := true
		for key, item := range val {
			if !first {
				buf.WriteString("\n")
				buf.WriteString(prefix)
			}
			first = false
			buf.WriteString(key)
			buf.WriteString(": ")
			buf.WriteString(marshalYAMLValue(item, prefix+"  "))
		}
