cat > cmd/yq/yaml.go << 'EOF'
package main

import (
	"bytes"
	"encoding/json"
	"strconv"
	"strings"
)

// SimpleYAMLParser is a basic YAML parser for common cases
func ParseSimpleYAML(data []byte) interface{} {
	lines := strings.Split(string(data), "\n")
	result, _ := parseYAMLLines(lines, 0)
	return result
}

func parseYAMLLines(lines []string, baseIndent int) (interface{}, int) {
	lines, idx := skipEmptyLines(lines)
	if len(lines) == 0 {
		return nil, idx
	}

	// Check if first line is an array
	firstLine := strings.TrimSpace(lines[0])
	if strings.HasPrefix(firstLine, "-") {
		return parseYAMLArray(lines, baseIndent)
	}

	// Check if it's a map
	if strings.Contains(firstLine, ":") {
		return parseYAMLMap(lines, baseIndent)
	}

	// Scalar value
	return parseScalarValue(firstLine), 1
}

func parseYAMLArray(lines []string, baseIndent int) ([]interface{}, int) {
	result := []interface{}{}
	processedCount := 0

	for i := 0; i < len(lines); i++ {
		line := lines[i]
		trimmed := strings.TrimSpace(line)

		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			processedCount++
			continue
		}

		indent := getIndent(line)

		if indent < baseIndent {
			break
		}

		if strings.HasPrefix(trimmed, "-") {
			content := strings.TrimPrefix(trimmed, "-")
			content = strings.TrimSpace(content)
			processedCount++

			if content == "" {
				// Complex value on next line
				remaining := lines[i+1:]
				nextIndent := indent + 2
				value, skip := parseYAMLLines(remaining, nextIndent)
				result = append(result, value)
				i += skip
				processedCount += skip
			} else {
				result = append(result, parseScalarValue(content))
			}
		} else {
			break
		}
	}

	return result, processedCount
}

func parseYAMLMap(lines []string, baseIndent int) (map[string]interface{}, int) {
	result := make(map[string]interface{})
	processedCount := 0

	for i := 0; i < len(lines); i++ {
		line := lines[i]
		trimmed := strings.TrimSpace(line)

		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			processedCount++
			continue
		}

		indent := getIndent(line)

		if indent < baseIndent {
			break
		}

		if strings.Contains(trimmed, ":") && !strings.HasPrefix(trimmed, "-") {
			parts := strings.SplitN(trimmed, ":", 2)
			if len(parts) == 2 {
				key := strings.TrimSpace(parts[0])
				value := strings.TrimSpace(parts[1])
				processedCount++

				if value == "" {
					// Value is on next line(s)
					remaining := lines[i+1:]
					nextIndent := indent + 2
					val, skip := parseYAMLLines(remaining, nextIndent)
					result[key] = val
					i += skip
					processedCount += skip
				} else {
					result[key] = parseScalarValue(value)
				}
			}
		} else if strings.HasPrefix(trimmed, "-") {
			// Array value
			break
		} else {
			break
		}
	}

	return result, processedCount
}

func parseScalarValue(s string) interface{} {
	s = strings.TrimSpace(s)

	if s == "" || s == "null" || s == "~" {
		return nil
	}

	if s == "true" {
		return true
	}

	if s == "false" {
		return false
	}

	// Try number
	if num, err := strconv.ParseFloat(s, 64); err == nil {
		return num
	}

	// Remove quotes
	if (strings.HasPrefix(s, "\"") && strings.HasSuffix(s, "\"")) ||
		(strings.HasPrefix(s, "'") && strings.HasSuffix(s, "'")) {
		return strings.Trim(s, "\"'")
	}

	return s
}

func getIndent(line string) int {
	count := 0
	for _, ch := range line {
		if ch == ' ' {
			count++
		} else {
			break
		}
	}
	return count
}

func skipEmptyLines(lines []string) ([]string, int) {
	count := 0
	for len(lines) > 0 {
		trimmed := strings.TrimSpace(lines[0])
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			lines = lines[1:]
			count++
		} else {
			break
		}
	}
	return lines, count
}

// MarshalYAML converts a value back to YAML format
func MarshalSimpleYAML(v interface{}, indent string) string {
	return marshalYAMLValue(v, indent)
}

func marshalYAMLValue(v interface{}, prefix string) string {
	var buf bytes.Buffer

	switch val := v.(type) {
	case nil:
		buf.WriteString("null")

	case bool:
		if val {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}

