package main

import (
	"bufio"
	"bytes"
	"encoding/base64"
	"encoding/csv"
	"encoding/json"
	"flag"
	"fmt"
	"net/url"
	"os"
	"strconv"
	"strings"
)

var (
	colors            = flag.Bool("C", false, "force print with colors")
	noColors          = flag.Bool("M", false, "force print with no colors")
	exitStatus        = flag.Bool("e", false, "set exit status if there are no matches or null or false is returned")
	help              = flag.Bool("h", false, "help for yq")
	inplace           = flag.Bool("i", false, "update the file in place of first file given")
	indent            = flag.Int("I", 2, "sets indent level for output")
	nullInput         = flag.Bool("n", false, "Don't read input, simply evaluate the expression given")
	noDoc             = flag.Bool("N", false, "Don't print document separators (---)")
	nulOutput         = flag.Bool("0", false, "Use NUL char to separate values")
	prettyPrint       = flag.Bool("P", false, "pretty print")
	unwrapScalar      = flag.Bool("r", true, "unwrap scalar")
	verbose           = flag.Bool("v", false, "verbose mode")
	version           = flag.Bool("V", false, "Print version information and quit")
	inputFormat       = flag.String("p", "auto", "parse format for input")
	outputFormat      = flag.String("o", "auto", "output format type")
	expression        = flag.String("expression", "", "forcibly set the expression argument")
	fromFile          = flag.String("from-file", "", "Load expression from specified file")
	csvSeparator      = flag.String("csv-separator", ",", "CSV Separator character")
	propertiesSep     = flag.String("properties-separator", " = ", "separator to use between keys and values")
	luaPrefix         = flag.String("lua-prefix", "return ", "prefix")
	luaSuffix         = flag.String("lua-suffix", ";\n", "suffix")
	luaUnquoted       = flag.Bool("lua-unquoted", false, "output unquoted string keys")
)

const Version = "v4.52.5"

func main() {
	flag.Parse()

	if *help {
		printHelp()
		os.Exit(0)
	}

	if *version {
